package com.vibeguard.samples.billing; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Manages the lifecycle of in-memory customer subscriptions. */ @RestController @RequestMapping("/api/subscriptions") public class SubscriptionController { private final Map<String,Subscription> subscriptions=new ConcurrentHashMap<>(); @PostMapping public ResponseEntity<Subscription> create(@Valid @RequestBody Request request){String id=UUID.randomUUID().toString();Subscription subscription=new Subscription(id,request.customerId(),request.plan(),"ACTIVE");subscriptions.put(id,subscription);return ResponseEntity.status(201).body(subscription);}@PostMapping("/{id}/cancel") public ResponseEntity<Subscription> cancel(@PathVariable String id){Subscription subscription=subscriptions.get(id);if(subscription==null)return ResponseEntity.notFound().build();Subscription cancelled=new Subscription(id,subscription.customerId(),subscription.plan(),"CANCELLED");subscriptions.put(id,cancelled);return ResponseEntity.ok(cancelled);}@GetMapping("/customer/{customerId}") public List<Subscription> status(@PathVariable String customerId){return subscriptions.values().stream().filter(item->item.customerId().equals(customerId)).toList();}record Request(@NotBlank String customerId,@NotBlank String plan){}record Subscription(String id,String customerId,String plan,String status){} }
